result.text:
export type Event = { turnId: string; kind: string; [key: string]: unknown };
export type Tool = { id: string; title: string; status: "pending" | "running" | "completed" | "failed"; output: string };
export type Turn = { text: string; tools: Tool[]; stopReason: string | null };

const STATUSES: ReadonlyArray<Tool["status"]> = ["pending", "running", "completed", "failed"];

function own(event: Event, key: string): unknown {
  return Object.prototype.hasOwnProperty.call(event, key) ? event[key] : undefined;
}

export function assembleTurn(turnId: string, events: Event[]): Turn {
  let text = "";
  let stopReason: string | null = null;
  const tools = new Map<string, Tool>();

  for (const event of events) {
    if (event.turnId !== turnId) continue;

    if (event.kind === "message") {
      const msg = own(event, "text");
      const value = typeof msg === "string" ? msg : "";
      if (own(event, "mode") === "replace") text = value;
      else text += value;
    } else if (event.kind === "tool") {
      const id = own(event, "id");
      if (typeof id !== "string") continue;
      let tool = tools.get(id);
      if (tool === undefined) {
        tool = { id, title: "", status: "pending", output: "" };
        tools.set(id, tool);
      }
      const title = own(event, "title");
      if (typeof title === "string") tool.title = title;
      const status = own(event, "status");
      if (typeof status === "string" && STATUSES.includes(status as Tool["status"])) {
        tool.status = status as Tool["status"];
      }
      const output = own(event, "output");
      if (output === null) tool.output = "";
      else if (typeof output === "string") {
        if (own(event, "outputMode") === "replace") tool.output = output;
        else tool.output += output;
      }
    } else if (event.kind === "done") {
      const reason = own(event, "stopReason");
      stopReason = typeof reason === "string" ? reason : null;
      break;
    }
  }

  return {
    text,
    tools: Array.from(tools.values(), (t) => ({ id: t.id, title: t.title, status: t.status, output: t.output })),
    stopReason,
  };
}
